function retentionLabel(x){return x.purgeAfter?'到期：'+new Date(x.purgeAfter).toLocaleString('zh-TW'):'待啟用 7 天保留期';}
'use strict';
const bulkDefinitions={
 cases:{title:'案件管理',key:'cases',section:'#admin-cases',label:x=>x.name+' · '+caseBatchLabel(x)},
 warehouse:{title:'庫房管理',key:'projects',section:'[data-section-key="warehouse"]',label:x=>x.name},
 plating:{title:'電鍍管理',key:'platingProjects',section:'[data-section-key="plating"]',label:x=>x.name,archive:true},
 wire:{title:'線材管理',key:'wireTypes',section:'#wire-admin',label:x=>x.name+wt('suffix'),archive:true},
 fields:{title:'自訂欄位',draft:'fields',section:'[data-section-key="fields"]',label:x=>x.label},
 pages:{title:'頁面與區塊',draft:'pages',section:'[data-section-key="pages"]',label:x=>x.title}
};
function bulkItems(kind,deleted=false){const d=bulkDefinitions[kind];return (d.draft?draftConfig()[d.draft]:state[d.key]||[]).filter(x=>!!x.archived===deleted).map(x=>({id:x.id,label:d.label(x)+(deleted?' · '+retentionLabel(x):'')}));}
function selectionDialog(title,items,action,onApply,note=''){
 if(currentUser.role!=='supervisor'||cloudBusy||failedCandidate)return;
 modal(title,'<p>'+esc(note)+'</p><div class="bulk-toolbar"><label><input type="checkbox" id="bulk-all">全選</label><span id="bulk-count">已選 0 筆</span></div><div class="bulk-list">'+items.map(item=>'<label class="bulk-choice"><input type="checkbox" name="bulkId" value="'+esc(String(item.id))+'" '+(item.reason?'disabled':'')+'><span>'+esc(item.label)+(item.reason?'<small>（'+esc(item.reason)+'）</small>':'')+'</span></label>').join('')+(!items.length?'<p>尚無可操作項目</p>':'' )+'</div>',action,async fd=>{const ids=fd.getAll('bulkId'),selected=items.filter(x=>ids.includes(String(x.id))&&!x.reason);if(!selected.length)throw Error('請先勾選項目');if(!await confirmAction('確定'+action+' '+selected.length+' 筆？\n'+selected.map(x=>x.label).join('\n')))return;await onApply(selected);$('#modal').close();renderAdmin();toast('已完成'+action+' '+selected.length+' 筆');});
 const inputs=[...document.querySelectorAll('[name=bulkId]:not(:disabled)')],all=$('#bulk-all'),submit=$('#submit-modal');const update=()=>{const count=inputs.filter(x=>x.checked).length;$('#bulk-count').textContent='已選 '+count+' 筆';submit.disabled=!count;all.checked=!!inputs.length&&count===inputs.length;all.indeterminate=count>0&&count<inputs.length;};all.onchange=()=>{inputs.forEach(x=>x.checked=all.checked);update();};inputs.forEach(x=>x.onchange=update);update();
}
async function applyBulkState(kind,items,restore=false){
 if(currentUser.role!=='supervisor'||cloudBusy||failedCandidate)throw Error('目前無法儲存，請先處理上方提示');const d=bulkDefinitions[kind],ids=new Set(items.map(x=>x.id)),next=structuredClone(state);
 if(d.draft){const draft=draftConfig();draft[d.draft]=draft[d.draft].filter(x=>!ids.has(x.id));next.contentDraft=draft;}
 else if(d.archive){for(const item of next[d.key]||[])if(ids.has(item.id)){if(restore){delete item.archived;delete item.deletedAt;delete item.purgeAfter;}else{item.archived=true;item.deletedAt=new Date().toISOString();item.purgeAfter=new Date(Date.now()+7*86400000).toISOString();}}}
 else if(kind==='warehouse'){next.deletedProjects??=[];next.projects.forEach((p,index)=>{if(ids.has(p.id))next.deletedProjects.unshift({project:p,index,deletedAt:new Date().toISOString(),purgeAfter:new Date(Date.now()+7*86400000).toISOString(),draft:drafts[p.id]||null});});next.projects=next.projects.filter(p=>!ids.has(p.id));}
 else next[d.key]=(next[d.key]||[]).filter(x=>!ids.has(x.id));
 state=next;for(const item of items)addAudit(restore?'還原':'刪除',item.label,'管理後台 > '+d.title,kind==='wire'?'wire:'+item.id:kind==='plating'?'plating:'+item.id:'');await saveCloud(state);if(failedCandidate)throw Error('尚未儲存成功，請處理上方提示');if(kind==='warehouse')for(const id of ids){delete drafts[id];if(selectedId===id)selectedId='';}
}
function openBulk(kind,onlyId,restore=false){const d=bulkDefinitions[kind];const items=bulkItems(kind,restore).filter(x=>!onlyId||x.id===onlyId);selectionDialog(d.title+' · '+(restore?'已刪除清單':onlyId?'刪除':'批量刪除'),items,restore?'還原':'刪除',selected=>applyBulkState(kind,selected,restore),restore?'勾選要還原的項目。刪除後保留 7 天，到期由伺服器每小時清理，永久刪除資料與所屬照片。':d.archive||kind==='warehouse'?'刪除後保留 7 天，可從已刪除清單還原；到期永久刪除資料與所屬照片。':d.draft?'從草稿移除；發布網站設定後才套用到前台。':'刪除後無法復原，請確認勾選項目。');}
function installBulkControls(){
 if(currentUser.role!=='supervisor')return;
 for(const [kind,d]of Object.entries(bulkDefinitions)){const section=document.querySelector(d.section);if(!section||section.querySelector('[data-bulk-kind]'))continue;const bar=document.createElement('div');bar.className='admin-actions';const button=document.createElement('button');button.type='button';button.dataset.bulkKind=kind;button.textContent='批量刪除';button.onclick=()=>openBulk(kind);bar.append(button);
 if(d.archive||kind==='warehouse'){const bin=document.createElement('button');bin.type='button';bin.textContent='已刪除清單';bin.onclick=()=>kind==='warehouse'?deletedProjectsDialog():openBulk(kind,null,true);bar.append(bin);}
 const body=section.querySelector('.admin-card-body')||section;body.prepend(bar);
 if(kind==='wire'){section.querySelectorAll('[data-wire-admin-open]').forEach(edit=>{const del=document.createElement('button');del.type='button';del.className='danger-button';del.textContent='刪除';del.onclick=()=>openBulk(kind,edit.dataset.wireAdminOpen);edit.after(del);});}
 if(kind==='plating'){section.querySelectorAll('[data-plating-admin-delete]').forEach(del=>del.onclick=()=>openBulk(kind,del.dataset.platingAdminDelete));}
 if(kind==='warehouse'){const list=document.createElement('div');list.className='bulk-warehouse-list';for(const item of bulkItems(kind)){const row=document.createElement('div');row.className='admin-row';row.innerHTML='<strong>'+esc(item.label)+'</strong>';const del=document.createElement('button');del.type='button';del.className='danger-button';del.textContent='刪除';del.onclick=()=>openBulk(kind,item.id);row.append(del);list.append(row);}body.append(list);}
 }
}
const adminBeforeBulk=renderAdmin;renderAdmin=function(){adminBeforeBulk();installBulkControls();};
const employeesBeforeBulk=loadEmployees;loadEmployees=async function(){await employeesBeforeBulk();if(currentUser.role!=='supervisor'||!$('#employee-list'))return;$('#bulk-employees')?.remove();const b=document.createElement('button');b.type='button';b.id='bulk-employees';b.textContent='批量刪除';$('#new-employee').after(b);b.onclick=()=>selectionDialog('員工權限 · 批量刪除',employeesCache.map(e=>({id:e.id,label:e.name+'｜'+e.email,reason:String(e.id)===String(currentUser.id)?'目前登入者不可刪除':''})),'刪除',async items=>{let done=0;for(const item of items){const employee=employeesCache.find(e=>e.id===item.id);const r=await apiFetch('/api/employees',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify(employee)}),data=await r.json();if(!r.ok){await loadEmployees();throw Error('已刪除 '+done+' 筆；'+item.label+'：'+data.error+'。請關閉並重新開啟清單。');}done++;addAudit('刪除員工帳號',item.label,'管理後台 > 員工權限');}await saveCloud(state);if(failedCandidate)throw Error('員工已刪除，但操作紀錄尚未儲存。');},'勾選員工後確認刪除；被刪除者將失去系統存取權限。');
 const panel=$('#permission-settings');if(panel&&!$('#bulk-profiles')){const button=document.createElement('button');button.type='button';button.id='bulk-profiles';button.textContent='批量刪除';panel.querySelector('.wire-tools').append(button);button.onclick=()=>selectionDialog('自訂權限 · 批量刪除',permissionProfiles.map(p=>({id:p.id,label:p.name,reason:p.builtin?'內建權限不可刪除':employeesCache.some(e=>e.profileId===p.id)?'仍有員工使用此權限':''})),'刪除',async items=>{for(const item of items)await permissionRequest({id:item.id},'DELETE');},'只可刪除未指派給員工的自訂權限。');}
};
const blocksBeforeBulk=openBlocks;openBlocks=function(id){blocksBeforeBulk(id);if(currentUser.role!=='supervisor')return;const button=document.createElement('button');button.type='button';button.textContent='批量刪除';$('main').prepend(button);button.onclick=()=>selectionDialog('頁面區塊 · 批量刪除',(draftConfig().pages.find(p=>p.id===id)?.blocks||[]).map(b=>({id:b.id,label:b.text||b.label||'空白區塊'})),'刪除',async items=>{const next=structuredClone(state),draft=draftConfig(),page=draft.pages.find(p=>p.id===id);page.blocks=page.blocks.filter(b=>!items.some(i=>i.id===b.id));next.contentDraft=draft;state=next;addAudit('刪除頁面區塊',items.map(x=>x.label).join('、'),'管理後台');await saveCloud(state);if(failedCandidate)throw Error('尚未儲存');},'只移除草稿中的區塊。');};
